/* ORDER — O Pecado da Misericórdia — prólogo solo, sem dependências externas */
'use strict';
const KEY='order_prologue_v4';
const DISCORD_INVITE='https://discord.gg/xVDAPBVTTz';
const ASSETS={logo:'assets/LOGO%20ORDER.png',searcher:{homem:{choice:'assets/Man.png',novel:'assets/Man_Visual.png',hell:'assets/Man_Hells_Visual.png'},mulher:{choice:'assets/Woman.png',novel:'assets/Woman_Visual.png',hell:'assets/Womans_Hells_Visual.png'}},elvira:{neutral:'assets/Euvira.png',transformed:'assets/Euvira_Demon.png'},eco:'assets/ORDER_Eco_do_Contrato_Sprite.png',guardian:'assets/ORDER_Guardiao_do_Prazo_Sprite.png'};
const EXPRESSIONS={neutral:{},happy:{},sad:{},afraid:{},suspicious:{},angry:{},crying:{},transformed:{}};
function searcherAsset(role='novel'){return (ASSETS.searcher[S.gender]||ASSETS.searcher.homem)[role]}
function portraitAsset(character,expression='neutral'){if(character==='searcher')return searcherAsset(expression==='transformed'?'hell':'novel');if(character==='eco'||character==='guardian')return ASSETS[character];return ASSETS.elvira[expression]||ASSETS.elvira.neutral}
const DEV_MODE=['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&new URLSearchParams(location.search).get('dev')==='1';
const $=q=>document.querySelector(q);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function roll(n){const array=new Uint32Array(1);const max=0x100000000;const limit=max-(max%n);do{crypto.getRandomValues(array)}while(array[0]>=limit);return(array[0]%n)+1}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=roll(i+1)-1;[r[i],r[j]]=[r[j],r[i]]}return r}
const SECTORS=['INCIDÊNCIA','RELAÇÃO','SOCIALISTA','JUSTIÇA','DOUTRINA'];
const DESCRIPTIONS={
 'INCIDÊNCIA':'Você suporta a pressão para que os outros possam continuar. Sua autoridade começa na resistência.',
 'RELAÇÃO':'Toda palavra possui duas lâminas. Você sabe quando negociar e quando agir.',
 'SOCIALISTA':'Você vê a força no coletivo. Proteger alguém pode mudar a sentença de todos.',
 'JUSTIÇA':'O poder não lhe interessa tanto quanto o veredito. Suas decisões têm peso.',
 'DOUTRINA':'Quando a verdade exige precisão, você prefere terminar o conflito antes que ele cresça.'
};
const QUESTIONS=[
 {q:'Um homem confessa um crime, mas pede uma segunda chance. Qual é sua primeira reação?',o:[['Imobilizá-lo. Primeiro, ninguém se machuca.','INCIDÊNCIA'],['Ouvir o que ele oferece e confrontar a história.','RELAÇÃO'],['Proteger as pessoas ao redor antes de decidir.','SOCIALISTA'],['Buscar as provas e aplicar uma sentença proporcional.','JUSTIÇA'],['Eliminar qualquer chance de fuga.','DOUTRINA']]},
 {q:'Seu parceiro está em perigo. O suspeito está prestes a escapar. Você...',o:[['Recebe o golpe no lugar dele.','INCIDÊNCIA'],['Cria um acordo para ganhar tempo.','RELAÇÃO'],['Organiza a retirada e ajuda seu parceiro.','SOCIALISTA'],['Escolhe a atitude que cause menos vítimas.','JUSTIÇA'],['Persegue e neutraliza a ameaça.','DOUTRINA']]},
 {q:'Você recebe uma ordem injusta de alguém muito poderoso.',o:[['Recusa e sustenta as consequências.','INCIDÊNCIA'],['Encontra um meio-termo para impedir o pior.','RELAÇÃO'],['Une outras pessoas para questionar a ordem.','SOCIALISTA'],['Exige que a ordem seja julgada pelos próprios princípios.','JUSTIÇA'],['Desobedece em silêncio e age por conta própria.','DOUTRINA']]},
 {q:'Qual destas ferramentas combina melhor com você?',o:[['Um escudo marcado por cicatrizes.','INCIDÊNCIA'],['Um documento com duas assinaturas.','RELAÇÃO'],['Um rádio que mantém todos conectados.','SOCIALISTA'],['Uma balança que não pode ser comprada.','JUSTIÇA'],['Uma lâmina escondida na manga.','DOUTRINA']]},
 {q:'Ao descobrir algo terrível sobre uma pessoa querida, você...',o:[['Não permite que ela machuque mais ninguém.','INCIDÊNCIA'],['Tenta compreendê-la, sem apagar os fatos.','RELAÇÃO'],['Apoia as vítimas e busca uma saída coletiva.','SOCIALISTA'],['Aplica o mesmo critério que aplicaria a um estranho.','JUSTIÇA'],['Age imediatamente, mesmo que fique sozinho.','DOUTRINA']]}
];
const ROOMS={
 escritorio:{name:'Escritório da Ordem',nr:'01',pos:[26,19],rect:[15,5,22,25],bg:SCENERY.arquivo,route:[[26,19],[35,29],[37,35],[37,57],[52,58]]},
 nave:{name:'Nave principal',nr:'02',pos:[52,44],rect:[40,5,25,47],bg:SCENERY.nave,route:[[52,44],[52,58]]},
 sacristia:{name:'Sacristia',nr:'03',pos:[80,19],rect:[68,5,24,25],bg:SCENERY.sacristia,clue:'keys',route:[[80,19],[69,29],[69,35],[69,55],[61,58],[52,58]]},
 arquivo:{name:'Arquivo de documentos',nr:'04',pos:[20,44],rect:[6,31,26,23],bg:SCENERY.arquivo,clue:'ledger',route:[[20,44],[32,50],[37,50],[37,57],[52,58]]},
 confessionario:{name:'Confessionário',nr:'05',pos:[85,44],rect:[74,31,23,23],bg:SCENERY.confessionario,clue:'letter',route:[[85,44],[74,51],[69,55],[61,58],[52,58]]},
 porao:{name:'Quarto trancado',nr:'06',pos:[13,72],rect:[3,55,21,32],bg:SCENERY.quarto,clue:'cellar',route:[[13,72],[23,60],[35,57],[52,58]]},
 reunioes:{name:'Sala de reuniões',nr:'07',pos:[35,74],rect:[26,61,18,26],bg:SCENERY.nave,route:[[35,74],[43,61],[52,58]]},
 corredor:{name:'Corredor dos fundos',nr:'08',pos:[66,74],rect:[59,60,15,27],bg:SCENERY.corredor,route:[[66,74],[61,65],[61,58],[52,58]]},
 patio:{name:'Pátio / abrigo da criança',nr:'09',pos:[86,74],rect:[76,60,21,28],bg:SCENERY.patio,clue:'child',route:[[86,74],[75,61],[68,57],[61,58],[52,58]]}
};
const CARD_LIBRARY={
 shot:{name:'Disparo Ritual',icon:'✦',dice:[1,2,3,4,5,6],text:'Causa 4 de dano a até 2 quadrados após acertar um D20.',effect:'attack',power:4,range:2},
 guard:{name:'Postura Firme',icon:'◇',dice:[1,2,3,4,5,6],text:'Recebe 5 de escudo contra o próximo dano.',effect:'shield',power:5},
 mend:{name:'Fôlego da Dívida',icon:'✚',dice:[1,2,3,4,5,6],text:'Recupera 5 pontos de Vida.',effect:'heal',power:5},
 expose:{name:'Veredito',icon:'⚖',dice:[1,2,3,4,5,6],text:'Causa 5 de dano e reduz em 1 o próximo golpe da inimiga.',effect:'attackWeak',power:5,range:2},
 step:{name:'Passo Silencioso',icon:'↗',dice:[1,2,3,4,5,6],text:'Ganha 2 passos extras e 2 de escudo.',effect:'move',power:2},
 signature:{name:'Marca do Setor',icon:'◎',dice:[1,2,3,4,5,6],text:'Uma ação exclusiva que canaliza a natureza do seu Setor.',effect:'signature',power:0,range:2}
};
function freshDeck(){return shuffle([...Array(5).fill('shot'),...Array(4).fill('guard'),...Array(3).fill('mend'),...Array(3).fill('expose'),...Array(3).fill('signature'),...Array(2).fill('step')].map((type,i)=>({uid:`c${i}`,type})))}
function defaultState(){return{version:4,volume:.45,textSpeed:32,stage:'intro',introOpened:false,evidenceId:'',gender:'',name:'',quizIndex:0,scores:Object.fromEntries(SECTORS.map(x=>[x,0])),sector:'',sin:'',audio:false,motionFull:false,node:'arrival',moral:4,trust:8,sanity:10,fame:0,clues:[],visited:[],currentRoom:'nave',flags:{},attempts:0,dialogHistory:[],combat:null,outcome:'',clock:0}}
function load(){try{let d=JSON.parse(localStorage.getItem(KEY));if(d&&d.version===4&&typeof d.stage==='string'){const {voice,...saved}=d;return {...defaultState(),...saved}}}catch{}return defaultState()}
const PREVIEW_SCENE=new URLSearchParams(typeof location==='undefined'?'':location.search).get('preview');
let S=load();
// Upgrade an ongoing encounter without restarting the campaign or losing evidence.
if(S.stage==='combat'&&S.combat){const c=S.combat;if(c.tutorialVersion!==CombatRules.tutorial.version){c.bossMax=CombatRules.tutorial.bossHp;c.bossHp=clamp(Number(c.bossHp)||0,0,c.bossMax);c.bossShield=clamp(Number(c.bossShield)||0,0,1);if(c.hp>0)c.hp=Math.max(c.hp,Math.min(c.maxHp,24));c.tutorialVersion=CombatRules.tutorial.version;c.last='MINI TUTORIAL · Todas as faces do D6 ativam cartas. No D20, o acerto começa em 2.'}c.intent=c.intent||CombatRules.plan(c.round||1,c.player);c.intent.cells=c.intent.cells||[]}
if(S.outcome==='victory'&&S.stage==='ending'&&!S.flags.communitySeen)S.stage='victory-eye';
if(PREVIEW_SCENE){
 S.name=S.name||'Procurador';S.sector=S.sector||'JUSTIÇA';
 if(PREVIEW_SCENE==='intro'){S.stage='intro';S.introOpened=false}
 if(PREVIEW_SCENE==='dialogue'){S.stage='vn';S.node='hell4'}
 if(PREVIEW_SCENE==='explore'){S.stage='explore';S.currentRoom='nave';S.visited=['nave']}
 if(PREVIEW_SCENE==='combat'){S.stage='combat';S.combat=null}
}
let toastTimer;
function persist(){if(PREVIEW_SCENE||DEV_MODE)return;try{localStorage.setItem(KEY,JSON.stringify(S))}catch{}}
function motionOK(){return S.motionFull||!window.matchMedia('(prefers-reduced-motion: reduce)').matches}
function patch(p){Object.assign(S,p);persist();render()}
function flash(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
function audio(type='click'){AudioEngine.play(type)}

function notifyRoll(text){document.querySelectorAll('.overlay-roll').forEach(el=>el.remove());const el=document.createElement('div');el.className='overlay-roll';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3800)}
function nav(){return `<div class="nav layer"><div class="wordmark"><img class="order-logo" src="${ASSETS.logo}" alt="ORDER" width="2048" height="683"></div><div class="nav-right"><span class="micro muted">PRÓLOGO · DEMONSTRAÇÃO SOLO</span><button class="btn btn-icon btn-ghost" data-action="audio" aria-label="Alternar efeitos sonoros">${S.audio?'♪ SOM LIGADO':'♪ SOM DESLIGADO'}</button><button class="btn btn-icon btn-ghost motion-toggle" data-action="motion" title="Forçar animações mesmo se as configurações do sistema as desabilitarem">${S.motionFull?'✧ EFEITOS ON':'✧ EFEITOS AUTO'}</button>${S.clues.length?'<button class="btn btn-icon btn-ghost" data-action="journal">DOSSIÊ</button>':''}<button class="btn btn-icon btn-ghost" data-action="settings" aria-label="Configurações">⚙</button><button class="btn btn-icon btn-ghost" data-action="restart" aria-label="Reiniciar jogo">↻</button></div></div>`}
function eyeSVG(){return `<svg class="order-eye" viewBox="0 0 360 230" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Olho sobrenatural rosa de ORDER"><defs><radialGradient id="eyeIris"><stop stop-color="#FF76C7"/><stop offset=".45" stop-color="#FF2F8E"/><stop offset="1" stop-color="#2A2A2F"/></radialGradient><clipPath id="eyeClip"><path d="M31 115C87 30 273 30 329 115C273 200 87 200 31 115Z"/></clipPath></defs><g class="eye-halo" fill="none" stroke="#FF76C7" opacity=".5"><circle cx="180" cy="115" r="102" stroke-dasharray="2 14"/><path d="M180 0V32M180 198V230M0 115H23M337 115H360M44 28L78 62M316 28L282 62M44 202L78 168M316 202L282 168"/></g><g class="eye-reveal"><path class="eye-outline-body" d="M31 115C87 30 273 30 329 115C273 200 87 200 31 115Z" fill="#190E19" stroke="#FF76C7" stroke-width="3"/><g clip-path="url(#eyeClip)"><g class="eye-iris-look"><circle cx="180" cy="115" r="57" fill="url(#eyeIris)" stroke="#FF76C7" stroke-width="2"/><circle cx="180" cy="115" r="43" fill="none" stroke="#D7D7DE" stroke-dasharray="2 5" opacity=".55"/><ellipse cx="180" cy="115" rx="16" ry="40" fill="#0C0C10"/><circle cx="167" cy="95" r="7" fill="white"/><circle cx="195" cy="131" r="3" fill="white" opacity=".6"/></g></g></g></svg>`}

function intro(){return `<section class="stage intro ${S.introOpened?'opened':''}"><div class="iris-burst" aria-hidden="true"></div><div class="intro-inner layer"><span class="eyebrow">ARQUIVO CENTRAL · DIVISÃO DE COBRANÇA</span>${!S.introOpened?`<button class="eye-button" data-action="open-eye" aria-label="Abrir o olho de ORDER">${eyeSVG()}</button><div class="micro muted">ELE JÁ SABE QUE VOCÊ ESTÁ AQUI.</div><div class="intro-tips">CLIQUE NO OLHO PARA INICIAR</div>`:`<div class="intro-brand"><img class="order-logo" src="${ASSETS.logo}" alt="ORDER" width="2048" height="683"></div><div class="intro-sub">A DÍVIDA NÃO TERMINA COM A MORTE.</div><div class="intro-button"><button class="btn btn-primary" data-action="create">ABRIR DOSSIÊ &nbsp; →</button></div><div class="intro-tips">PRIMEIRO CONTRATO / 001</div>`}</div></section>`}
function stepLine(a){return `<div class="step-line">${[1,2,3].map(i=>`<span class="${i<=a?'done':''}"></span>`).join('')}</div>`}
function creator(){
 const stage=S.stage;
 let inner='';let step=1;
 if(stage==='gender')return `<section class="stage creator creator-selection">${nav()}<main class="identity-selection layer"><div class="identity-heading"><span class="eyebrow">ORDER · IDENTIDADE</span><h1>Escolha seu Searcher</h1><p>Selecione o personagem para continuar.</p></div><div class="gender-grid">${[['homem','Man.png','HOMEM'],['mulher','Woman.png','MULHER']].map(([id,file,label])=>`<button class="choice-gender searcher-choice" data-action="gender" data-value="${id}" aria-label="Escolher Searcher ${label.toLowerCase()}"><img src="assets/${file}" alt="Searcher ${label.toLowerCase()} de corpo inteiro"><span class="identity-caption"><strong>${label}</strong><small>SELECIONAR →</small></span></button>`).join('')}</div><p class="identity-note">O rosto é seu. A dívida também.</p></main></section>`;
 if(stage==='name'){
 inner=`<div class="eyebrow">ENTREVISTA · 01 / IDENTIDADE</div><h1 class="hero-title">Seu nome ainda<br>é seu?</h1><p class="hero-copy">Há nomes riscados dos registros. O seu ainda pode ser escrito.</p>${stepLine(1)}<label for="player-name" class="eyebrow">NOME DO SEARCHER</label><input id="player-name" class="form-input" maxlength="24" placeholder="Escreva seu nome" autocomplete="off" value="${esc(S.name)}"><button class="btn btn-primary" data-action="submit-name">CONFIRMAR CREDENCIAL &nbsp; →</button>`;
 }else if(stage==='quiz'){
 step=2;const q=QUESTIONS[S.quizIndex];inner=`<div class="eyebrow">ENTREVISTA · 02 / ANÁLISE DE PERFIL</div><h1 class="hero-title">${esc(q.q)}</h1><p class="hero-copy">Não existem respostas inocentes. Cada decisão revela uma inclinação do seu Setor.</p>${stepLine(step)}<div class="quiz-choices">${q.o.map((o,i)=>`<button class="quiz-choice" data-action="answer" data-value="${i}"><b>${String.fromCharCode(65+i)}</b><span>${esc(o[0])}</span></button>`).join('')}</div><span class="save-note">PERGUNTA ${S.quizIndex+1} DE ${QUESTIONS.length} • SEUS RESULTADOS NÃO SERÃO EXIBIDOS ATÉ O FINAL</span>`;
 }else if(stage==='sin'){
 step=3;inner=`<div class="eyebrow">ENTREVISTA · 03 / CONFISSÃO</div><h1 class="hero-title">Qual é o seu<br>maior pecado?</h1><p class="hero-copy">Escreva uma resposta <b>ficcional</b> para seu Searcher. Você pode deixar em branco. A resposta servirá, no máximo, como critério leve de desempate entre Setores.</p>${stepLine(step)}<label class="eyebrow" for="sin-entry">CONFISSÃO DE VIDA</label><textarea id="sin-entry" class="sin-input" maxlength="300" placeholder="Escreva a confissão do seu personagem...">${esc(S.sin)}</textarea><button class="btn btn-primary" data-action="submit-sin">ASSINAR CONFISSÃO &nbsp; →</button><p class="save-note">ESTE PRÓLOGO ARMAZENA A RESPOSTA APENAS NESTE NAVEGADOR.</p>`;
 }else if(stage==='class'){
 inner=`<div class="eyebrow">RESULTADO DA ENTREVISTA · ACESSO CONCEDIDO</div><h1 class="hero-title">Seu destino foi<br>classificado.</h1><div class="result-crest">✧</div><div class="eyebrow">SETOR DESIGNADO</div><div class="class-label">${esc(S.sector)}</div><p class="hero-copy">${esc(DESCRIPTIONS[S.sector])}</p><div class="line"></div><div class="eyebrow">EQUIPAMENTOS DE INGRESSO</div><div class="loadout"><div><b>PISTOLA DE SERVIÇO</b><small>Ataque básico: 2 de dano, alcance de 2 quadrados. Requer teste de D20.</small></div><div><b>PAPEL E CANETA</b><small>Durante combate, compre 1 carta adicional. Recarga de 2 turnos próprios.</small></div></div><div class="small muted">Seu baralho inicial terá 20 cartas. A mão aparece apenas no combate; os diálogos seguem o sistema de Visual Novel.</div><br><button class="btn btn-primary" data-action="begin-story">ACEITAR O PRIMEIRO CONTRATO &nbsp; →</button>`;
 }
 return `<div class="stage creator">${nav()}<div class="creator-panel corner layer fade-in"><header class="dossier-heading"><div><span>DIVISÃO DE COBRANÇA · ARQUIVO DE PESSOAL</span><strong>Ficha de Procurador</strong></div><div class="dossier-photo"><img src="${searcherAsset('choice')}" alt="Retrato de identificação do Searcher"></div><div class="dossier-serial">OR / 001<br><b>CONFIDENCIAL</b></div></header>${inner}<div class="dossier-signature"><span>REGISTRO INDIVIDUAL</span><span>ASSINATURA DO SEARCHER</span></div></div><div class="footer-note layer">ORDER · ARQUIVO 001 · A MORTE NÃO APAGA OS DEVERES.</div></div>`;
}
function characterHTML(id,expression='neutral'){const speaker=({elvira:'Dona Elvira',eco:'Eco do Contrato',guardian:'Guardião do Prazo'})[id]||S.name||'Searcher';return `<div class="portrait-wrap character ${id} ${id==='searcher'?'':'right-character'}" data-character="${id}" data-expression="${expression}"><div class="character-light"></div><div class="character-art"><img src="${portraitAsset(id,expression)}" alt="${esc(speaker)}" decoding="async"></div></div>`}
function vn(){const n=NODES[S.node]||NODES.arrival,choices=typeof n.choices==='function'?n.choices():n.choices||[],phrase=typeof n.text==='function'?n.text():n.text;const infernal=S.node.startsWith('hell'),guest=n.character||(n.portrait?'elvira':'');return `<section class="stage vn" data-scene="${esc(S.node)}"><div class="scene-bg" style="background-image:url('${n.image}')"></div><div class="scene-light-wash" aria-hidden="true"></div><div class="horror-silhouette" aria-hidden="true"></div>${nav()}<div class="scene-title">${infernal?'HELLS · PORTÃO ZERO':'CÓMUM · IGREJA DE SANTA CECÍLIA'}</div><div class="vn-content">${characterHTML('searcher',infernal?'transformed':'neutral')}${guest?characterHTML(guest,S.node==='hell5'?'transformed':n.expression||'neutral'):''}</div><div class="vn-footer"><div class="dialogue corner"><div class="who">${esc(n.speaker)}</div><div class="text typewritten" role="button" tabindex="0" aria-label="Revelar a fala; clicar novamente para continuar" data-full="${esc(phrase)}"></div><div class="dialogue-choices is-waiting" inert>${choices.map((c,i)=>`<button class="btn btn-ghost" data-action="${c[1]}" data-value="${c[2]}"><span class="rose">${i+1}.</span> ${esc(c[0])}</button>`).join('')}</div><span class="dialogue-hint">CLIQUE PARA REVELAR A FALA · DEPOIS, ESCOLHA COMO AGIR</span></div><div class="vn-steps"><span>${esc(S.name.toUpperCase())} · ${esc(S.sector)}</span><span>MORAL ${S.moral}/10 · CONFIANÇA ${S.trust}/10 · DOSSIÊ ${S.clues.length}/${Object.keys(CLUES).length}</span></div></div></section>`}

function meter(name,value,max){const percent=clamp(Math.round((value/max)*100),0,100);return `<div><div class="stat-row"><span>${name}</span><b>${value} / ${max}</b></div><div class="stat-bar"><i style="--percent:${percent}%"></i></div></div>`}
function explore(){return `<section class="stage explore">${nav()}<div class="main-container layer explore-inner"><div class="mission-top"><div><div class="eyebrow">CONTRATO Nº 001 · CÓMUM</div><h1>Santa Cecília</h1><div class="muted">Observe as salas. Ouça as pessoas. Uma evidência não conta toda a história.</div></div><button class="btn btn-ghost" data-action="talk">CONVERSAR COM ELVIRA →</button></div><div class="explore-body"><div class="panel corner"><div class="panel-title">IGREJA DE SANTA CECÍLIA</div><div class="church-map-frame"><div class="floor-map" role="group" aria-label="Mapa da igreja com nove cômodos clicáveis">${Object.entries(ROOMS).map(([id,r])=>`<button class="map-room ${S.visited.includes(id)?'visited':''} ${S.currentRoom===id?'current':''}" style="left:${r.rect[0]}%;top:${r.rect[1]}%;width:${r.rect[2]}%;height:${r.rect[3]}%" data-action="room" data-value="${id}" aria-label="Entrar em ${r.name}"><span class="rno">${r.nr}</span><span class="rname">${r.name}</span><span class="rstatus">${r.clue&&S.clues.includes(r.clue)?'REGISTRO ARQUIVADO':'VISITAR →'}</span></button>`).join('')}<div class="map-center">CORREDOR<br>CENTRAL</div><div class="map-token" style="--token-x:${ROOMS[S.currentRoom].pos[0]}%;--token-y:${ROOMS[S.currentRoom].pos[1]}%" aria-hidden="true"><img src="${searcherAsset('choice')}" alt=""></div></div></div><div class="small muted" style="margin-top:8px">Seu retrato representa seu Searcher. O movimento entre salas é animado.</div></div><aside class="panel corner explore-side"><div class="panel-title">DOSSIÊ DO SEARCHER</div><div class="serif" style="font-size:29px">${esc(S.name)}</div><div class="small muted">SETOR ${esc(S.sector)}</div><div class="stat-list" style="margin-top:14px">${meter('MORAL',S.moral,10)}${meter('CONFIANÇA',S.trust,10)}${meter('SANIDADE',S.sanity,10)}</div><div class="line"></div><div class="panel-title">ARQUIVO · ${S.clues.length} PEÇAS</div><div class="evidence-list">${Object.entries(CLUES).map(([id,c])=>S.clues.includes(id)?`<button class="evidence found evidence-button" data-action="reread" data-value="${id}"><span class="dot"></span><span>${esc(c.label)} ↗</span></button>`:'').join('')||'<div class="small muted">Seu arquivo ainda está vazio.</div>'}</div><div class="mission-actions"><button class="btn btn-primary btn-wide" data-action="confront">DECIDIR O JULGAMENTO →</button><span class="save-note">NÃO HÁ RESPOSTAS ASSINALADAS COMO CORRETAS.</span></div></aside></div></div></section>`}
function evidence(){const e=CLUES[S.evidenceId]||CLUES.ledger;return `<section class="stage evidence-stage" style="--evidence-background:url('${e.room==='porao'?SCENERY.quarto:ROOMS[e.room]?.bg||SCENERY.arquivo}')">${nav()}<div class="evidence-wrap layer"><div class="eyebrow">ARQUIVO 001 · MATERIAL COLETADO</div><div class="evidence-paper"><div class="evidence-stamp">OR / 001</div><div class="eyebrow">${esc(e.location)}</div><h1>${esc(e.title)}</h1><p class="evidence-content">${esc(e.text)}</p><div class="evidence-scribble">${esc(e.description)}</div></div><div class="evidence-actions"><button class="btn btn-ghost" data-action="journal">COMPARAR REGISTROS</button><button class="btn btn-primary" data-action="store-evidence">GUARDAR NO DOSSIÊ →</button></div></div></section>`}
function veil(){return `<section class="stage veil"><div class="veil-blink" aria-hidden="true"></div><div class="veil-content"><div class="eyebrow">CONTRATO REGISTRADO · RETORNO</div><h1 class="hero-title">Sua assinatura<br>atravessou o véu.</h1><p>A próxima voz já conhece sua decisão.</p><button class="btn btn-primary" data-action="wake-hell">ABRIR OS OLHOS &nbsp; →</button></div></section>`}
function initialCombat(){const pile=freshDeck(),hand=pile.splice(0,S.sector==='RELAÇÃO'?4:3),player={x:1,y:2};return{hp:34+(S.sector==='SOCIALISTA'?2:0),maxHp:34+(S.sector==='SOCIALISTA'?2:0),shield:S.sector==='INCIDÊNCIA'?4:S.sector==='SOCIALISTA'?2:0,bossHp:CombatRules.tutorial.bossHp,bossMax:CombatRules.tutorial.bossHp,bossShield:0,tutorialVersion:CombatRules.tutorial.version,player,boss:{x:5,y:2},move:2,action:1,round:1,pile,hand,discard:[],banned:[],paperCd:0,usedBurn:false,weak:0,badRolls:0,intent:CombatRules.plan(1,player),log:['O Portão Zero observa sua decisão.'],phase:'player',last:'MINI TUTORIAL · Mova-se até os quadrados iluminados. A Pistola alcança 2 quadrados; cartas ativam em qualquer face do D6.'}}
function enemyName(){return S.flags.route==='mercy'?'Eco do Contrato':S.flags.route==='defer'?'Guardião do Prazo':'Dona Elvira'}
function isAlternate(){return ['mercy','defer'].includes(S.flags.route)}
function enemyAsset(){return S.flags.route==='mercy'?ASSETS.eco:S.flags.route==='defer'?ASSETS.guardian:ASSETS.elvira.transformed}
function needsTarget(card){return ['attack','attackWeak'].includes(card.effect)||(card.effect==='signature'&&['JUSTIÇA','DOUTRINA'].includes(S.sector))}

const WALLS=new Set(); // A nova arena do Hells é aberta; a borda delimita a área jogável.
const dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
function inBounds(x,y){return x>=0&&x<9&&y>=0&&y<5&&!WALLS.has(`${x},${y}`)}
function pathLength(start,end,block){if(!inBounds(end.x,end.y))return Infinity;const queue=[{...start,d:0}],seen=new Set([`${start.x},${start.y}`]);for(let i=0;i<queue.length;i++){const q=queue[i];if(q.x===end.x&&q.y===end.y)return q.d;for(let [dx,dy] of [[0,1],[0,-1],[1,0],[-1,0]]){let x=q.x+dx,y=q.y+dy,k=`${x},${y}`;if(inBounds(x,y)&&!seen.has(k)&&(!block||!(x===block.x&&y===block.y))){seen.add(k);queue.push({x,y,d:q.d+1})}}}return Infinity}
let selectedCardId=null;
let knownHandCards=new Set();
function cardSymbol(type){return {shot:'✦',guard:'◇',mend:'✚',expose:'⚖',step:'➜',signature:'◉'}[type]||'◉'}
function combat(){const c=S.combat;if(!c)return'';
 const canAttack=dist(c.player,c.boss)<=CombatRules.pistol.range;
 if(selectedCardId&&!c.hand.some(x=>x.uid===selectedCardId))selectedCardId=null;
 const selected=c.hand.find(x=>x.uid===selectedCardId);
 const handCount=c.hand.length;
 const freshHandCards=new Set(c.hand.filter(card=>!knownHandCards.has(card.uid)).map(card=>card.uid));
 knownHandCards=new Set(c.hand.map(card=>card.uid));
 return `<section class="stage combat ${c.bossHp<=c.bossMax/2?'enraged':''}">${nav()}<div class="combat-top layer"><div class="combat-chapter"><span class="eyebrow">MINI TUTORIAL · HELLS</span><strong>${isAlternate()?'O PESO DA SUA ASSINATURA':'A MISERICÓRDIA CORROMPIDA'}</strong></div><div class="turn-indicator">RODADA ${c.round} <span class="turn-dot"></span> ${c.phase==='player'?'SUA VEZ DE AGIR':'O ADVERSÁRIO AGE'}</div></div>
 <div class="combat-layout layer"><aside class="combat-hud hud-left"><div class="fighter compact-fighter"><div class="eyebrow">SEARCHER / ${esc(S.sector)}</div><div class="fighter-name">${esc(S.name)}</div><div class="stat-list">${meter('VIDA',c.hp,c.maxHp)}${meter('ESCUDO',c.shield,20)}${meter('MORAL',S.moral,10)}${meter('SANIDADE',S.sanity,10)}</div><div class="line"></div><div class="small muted">AÇÕES ${c.action} · MOVIMENTO ${c.move}</div></div><div class="fighter small-fighter"><div class="eyebrow">EQUIPAMENTOS</div><button class="quick-equip" data-action="shoot" ${c.phase!=='player'||c.action===0||!canAttack?'disabled':''}>⌖ <span>PISTOLA<br><small>2 DANO · 2 QUADRADOS</small></span></button><button class="quick-equip ${c.paperCd>0?'is-tapped':''}" data-action="paper" ${c.phase!=='player'||c.paperCd>0?'disabled':''}>✎ <span>PAPEL E CANETA<br><small>${c.paperCd>0?`RECARGA · ${c.paperCd} TURNO(S)`:'COMPRAR 1 CARTA · CD 2'}</small></span></button></div></aside>
 <main class="fight-area"><div class="combat-board-wrap"><div class="combat-floor" role="group" aria-label="Arena com nove colunas e cinco linhas">${Array.from({length:5},(_,y)=>Array.from({length:9},(_,x)=>{const isPlayer=x===c.player.x&&y===c.player.y,isEnemy=x===c.boss.x&&y===c.boss.y,wall=WALLS.has(`${x},${y}`),reachable=c.phase==='player'&&c.move>0&&!isPlayer&&!isEnemy&&!wall&&pathLength(c.player,{x,y},c.boss)<=c.move;return `<button class="tile ${wall?'wall':''} ${isEnemy?'enemy':''} ${reachable?'accessible':''} ${c.intent.cells.some(p=>p.x===x&&p.y===y)?'danger-tile':''} ${isEnemy&&selected&&needsTarget(CARD_LIBRARY[selected.type])&&dist(c.player,c.boss)<=2?'targetable':''}" data-action="${isEnemy&&selected?'play-card':'move'}" data-value="${isEnemy&&selected?selected.uid:x+','+y}" ${!reachable&&!(isEnemy&&selected&&needsTarget(CARD_LIBRARY[selected.type])&&dist(c.player,c.boss)<=2)?'disabled':''} aria-label="Quadrado ${x+1} por ${y+1}${reachable?', mover personagem':''}">${isPlayer?`<span class="unit player"><img src="${searcherAsset('choice')}" alt="${esc(S.name)}"></span>`:isEnemy?`<span class="unit boss"><img src="${enemyAsset()}" alt="${esc(enemyName())}"></span>`:''}</button>`}).join('')).join('')}</div></div><div class="battle-message">${esc(c.last)}<span class="enemy-intent-mobile" style="display:none">${esc(CombatRules.intent(c))}</span></div><div class="board-controls"><span>MARQUE UMA CÉLULA PARA SE MOVER · <b>${c.move} PASSOS</b></span><button class="btn btn-primary" data-action="end-turn" ${c.phase!=='player'?'disabled':''}>ENCERRAR TURNO →</button></div></main>
 <aside class="combat-hud hud-right"><div class="fighter compact-fighter boss-panel"><div class="eyebrow">ALMA CONDENADA</div><div class="fighter-name">${enemyName()}</div><div class="boss-portrait"><img src="${enemyAsset()}" alt="${esc(enemyName())}"></div>${meter('VIDA',c.bossHp,c.bossMax)}<div class="enemy-intent"><b>INTENÇÃO</b>${esc(CombatRules.intent(c))}${c.bossShield?'<br>ESCUDO '+c.bossShield:''}</div></div><div class="fighter small-fighter"><div class="eyebrow">DECK</div><div class="piles"><span>COMPRA <b>${c.pile.length}</b></span><span>DESCARTE <b>${c.discard.length}</b></span><span>BANIDAS <b>${c.banned.length}</b></span></div></div></aside></div>
 <section class="hand-section layer" aria-label="Sua mão de cartas"><div class="hand-glow"></div><div class="hand-label">SUA MÃO <b>${handCount}</b> <span>• CLIQUE EM UMA CARTA PARA INSPECIONAR</span></div><div class="cards" style="--hand-count:${handCount}">${c.hand.map((card,i)=>{const d=CARD_LIBRARY[card.type];const t=i-(handCount-1)/2;const angle=t*4.8;return `<button class="card-item ${freshHandCards.has(card.uid)?'is-dealt':''} ${selectedCardId===card.uid?'is-selected':''}" style="--card-rotation:${angle}deg;--order:${i};" data-action="select-card" data-value="${card.uid}" aria-label="Selecionar ${esc(d.name)}" aria-pressed="${selectedCardId===card.uid}"><span class="card-corner">O / ${String(i+1).padStart(2,'0')}</span><strong class="card-name">${esc(d.name)}</strong><span class="card-illustration">${cardSymbol(card.type)}</span><span class="card-desc">${esc(d.text)}</span><span class="card-dice">D6 <b>${d.dice.join(' · ')}</b></span></button>`}).join('')}</div><div class="hand-footer">20 CARTAS NO DECK · D6 ATIVA A HABILIDADE · D20 RESOLVE O ATAQUE</div></section>
 ${selected?`<aside class="card-inspector layer"><div class="eyebrow">CARTA SELECIONADA</div><h3>${esc(CARD_LIBRARY[selected.type].name)}</h3><p>${esc(CARD_LIBRARY[selected.type].text)}</p><div class="inspector-dice">RESULTADOS VÁLIDOS NO D6: ${CARD_LIBRARY[selected.type].dice.join(' / ')}</div><div class="inspector-actions"><button class="btn btn-primary" data-action="play-card" data-value="${selected.uid}" ${c.action<1||c.phase!=='player'?'disabled':''}>USAR CARTA</button><button class="btn btn-ghost" data-action="burn" data-value="${selected.uid}" ${c.usedBurn||c.phase!=='player'?'disabled':''}>QUEIMAR · BANIR · +2 PASSOS</button></div><button class="inspector-close" data-action="select-card" data-value="">✕</button></aside>`:''}
 </section>`;
}
function victoryEye(){return `<section class="stage intro victory-eye"><div class="intro-inner layer"><span class="eyebrow">MINI TUTORIAL CONCLUÍDO</span><button class="eye-button" data-action="reveal-community" aria-label="Abrir o convite da comunidade ORDER">${eyeSVG()}</button><h1>O contrato foi encerrado.</h1><p>O próximo passo está do outro lado.</p><div class="intro-tips">CLIQUE NO OLHO PARA CONTINUAR</div></div></section>`}
function community(){return `<section class="stage community-stage"><div class="community-inner layer"><img class="community-logo" src="${ASSETS.logo}" alt="ORDER" width="2048" height="683"><div class="community-paper"><span class="eyebrow">SEU PRIMEIRO CONTRATO TERMINOU</span><h1>A Ordem espera por você.</h1><p>Entre no nosso grupo do Discord para conhecer a comunidade, acompanhar o projeto e continuar essa história.</p><a class="btn btn-primary community-join" href="${DISCORD_INVITE}" target="_blank" rel="noopener noreferrer">ENTRAR NO GRUPO DO DISCORD ↗</a><button class="btn btn-ghost" data-action="view-ending">LER O RESULTADO DO MEU JULGAMENTO</button></div><button class="btn btn-ghost" data-action="postgame-eye">VOLTAR AO OLHO</button></div></section>`}
function ending(){const won=S.outcome==='victory',route=S.flags.route||'collect';const title=!won?'Sua assinatura ainda pesa.':route==='mercy'?'Elvira continua na Terra.':route==='defer'?'Uma noite a mais.':'Contrato encerrado.';const desc=!won?'O Portão o derrubou. Sua decisão permanece no arquivo. Você pode tentar novamente com o mesmo compromisso.':route==='mercy'?'O Eco se desfaz; a dívida não. Na igreja, Elvira abre o caderno diante da mãe de Lia. O que fará com os nomes ainda depende dela. Você assumiu a suspensão, e uma parcela passa a constar sob a sua assinatura.':route==='defer'?'O Guardião cede. O contrato retorna à sua pasta com um novo prazo. Ao amanhecer, Elvira deverá apresentar as cartas que faltam. Não houve absolvição nem cobrança. Seu próximo retorno decidirá o que a espera comprou.':'O véu de Elvira se desfaz. As mãos deixam de prender. Não há aplauso nem voz dizendo que você julgou bem. Na Terra, alguém encontrará a sopa fria. O arquivo registra a parcela recebida.';return `<section class="stage ending"><div class="ending-card corner layer"><div class="eyebrow">ORDER V0.4.3 · PROCESSO 001 · ${won?'REGISTRADO':'INTERROMPIDO'}</div><h1 class="cinematic-title">${title.split('').map((l,i)=>'<span style="--letter:'+i*.15+'">'+(l===' '?'&nbsp;':esc(l))+'</span>').join('')}</h1><p>${desc}</p><p class="ending-context">${S.clues.includes('child')?'Lia foi ouvida e permanece sob proteção.':'O testemunho de Lia não consta no processo.'} ${S.flags.notes?.length?'Suas perguntas acompanham os registros.':''} ${S.flags.aggressive?'Elvira se recordará da ameaça na igreja.':''}</p><div class="line"></div><div class="small muted">${esc(S.name)} · ${esc(S.sector)} · ${S.clues.length} REGISTROS<br>MORAL ${S.moral}/10 · CONFIANÇA ${S.trust}/10 · SANIDADE ${S.sanity}/10 · HELL OF FAME ${S.fame}</div><div class="ending-actions">${!won?'<button class="btn btn-primary" data-action="retry-boss">TENTAR NOVAMENTE</button>':'<button class="btn btn-primary" data-action="postgame-eye">CONTINUAR →</button>'}<button class="btn btn-ghost" data-action="journal">REVER DOSSIÊ</button><button class="btn btn-ghost" data-action="restart">REINICIAR</button></div><div class="footer-note">FIM DO PRÓLOGO · O JULGAMENTO DOS OUTROS NÃO ABSOLVE O SEU.</div></div></section>`}

function render(){const breathing=[...document.querySelectorAll('.character')].map(el=>({id:el.dataset.character,src:el.querySelector('img').getAttribute('src'),time:el.querySelector('img').getAnimations()[0]?.currentTime}));Cinematics.cancelTypewriter();document.documentElement.dataset.motion=S.motionFull?'full':'auto';const stages={intro,gender:creator,name:creator,quiz:creator,sin:creator,class:creator,vn,explore,evidence,veil,combat,ending,'victory-eye':victoryEye,community};$('#app').innerHTML=(stages[S.stage]||intro)();document.title='ORDER V0.4.3 — O Pecado da Misericórdia';Cinematics.playCharacterBreathing();for(const b of breathing){const img=document.querySelector('.character.'+b.id+' img');if(img?.getAttribute('src')===b.src&&b.time!=null){const a=img.getAnimations()[0];if(a)a.currentTime=b.time}}if(S.stage==='vn')runTypewriter();if(S.stage==='intro'&&!S.introOpened||S.stage==='victory-eye')Cinematics.playEyeIntro();if(DEV_MODE)mountDevPanel()}
function runTypewriter(){const el=$('.typewritten'),choices=$('.dialogue-choices'),n=NODES[S.node];if(!el)return;Cinematics.startTypewriter(el,el.dataset.full,{speaker:n.speaker==='DONA ELVIRA'?'elvira':n.speaker==='SEARCHER'?'searcher':'voice',onDone:()=>{choices.classList.remove('is-waiting');choices.inert=false;$('.dialogue-hint').textContent=choices.children.length===1?'CLIQUE NA FALA OU PRESSIONE ESPAÇO PARA CONTINUAR':'ESCOLHA SUA RESPOSTA'}})}
function advanceDialogue(){if(Cinematics.busy)return;if(Cinematics.finishTypewriter())return;const choices=$('.dialogue-choices');if(choices&&!choices.inert&&choices.children.length===1)choices.firstElementChild.click()}


function goNode(id){if(!NODES[id]){flash('Cena indisponível: '+id);return}const previous=NODES[S.node],next=NODES[id];const update=()=>{S.node=id;S.stage='vn';persist();render();if(['judgment','hell1'].includes(id))Cinematics.showTitle(id==='judgment'?'SEU JULGAMENTO COMEÇOU':'BEM-VINDO AO HELLS');if(id==='arrival')audio('bell');if(next.horror&&!S.flags['event_'+id]){S.flags['event_'+id]=true;setTimeout(()=>{if(S.stage==='vn'&&S.node===id)Cinematics.playHorrorEvent(next.horror)},1100)}if(id==='nave'&&S.flags.photoSeen&&!S.flags.photoReturned){S.flags.photoReturned=true;setTimeout(()=>{if(S.stage==='vn'&&S.node===id)Cinematics.playHorrorEvent('portrait')},1100)}if(id==='hell4')setTimeout(()=>{if(S.stage==='vn'&&S.node===id)Cinematics.transformation()},1800)};if(S.stage!=='vn'||previous?.image!==next.image)Cinematics.transitionScene(update,{blink:id==='hell1'});else update()}

function giveClue(id){const clue=CLUES[id];if(!clue)return;if(id==='photo')S.flags.photoSeen=true;S.evidenceId=id;patch({stage:'evidence'});audio('paper');if(['letter','notebook'].includes(id)&&!S.flags['horror_'+id]){S.flags['horror_'+id]=true;setTimeout(()=>{if(S.stage==='evidence'&&S.evidenceId===id)Cinematics.playHorrorEvent()},900)}}
function collect(){S.sanity=clamp(S.sanity-1,0,10);Cinematics.transitionScene(()=>patch({stage:'veil'}));audio('breath');}
async function enterRoom(id){const r=ROOMS[id];if(!r||Cinematics.busy)return;if(S.stage!=='explore'){patch({stage:'explore'});requestAnimationFrame(()=>enterRoom(id));return}if(id===S.currentRoom){goNode(id);return}const token=$('.map-token'),map=$('.floor-map'),rect=map.getBoundingClientRect(),origin=ROOMS[S.currentRoom]||ROOMS.nave;const route=[...(origin.route||[origin.pos,[52,58]]),...(r.route||[r.pos,[52,58]]).slice().reverse().slice(1)].filter((p,i,all)=>!i||p[0]!==all[i-1][0]||p[1]!==all[i-1][1]);const points=route.map(([x,y])=>({x:x*rect.width/100,y:y*rect.height/100}));$('.map-room[data-value="'+id+'"]').classList.add('path-preview');await Cinematics.walkToTile(points,{element:token,stepMs:210});S.currentRoom=id;if(!S.visited.includes(id))S.visited.push(id);persist();goNode(id)}

function getCard(c,uid){return c.hand.find(x=>x.uid===uid)}
function drawCard(c,num=1){for(let i=0;i<num;i++){if(c.hand.length>=7){c.log.push('Limite de 7 cartas na mão; compra cancelada.');return}if(!c.pile.length){if(!c.discard.length)return;c.pile=shuffle(c.discard);c.discard=[];c.log.push('O descarte foi embaralhado.')}c.hand.push(c.pile.shift())}}
function record(c,msg){c.last=msg;c.log.push(msg);if(c.log.length>50)c.log.shift();persist();render()}
function attackRoll(c,damage,name,extraWeak=false){if(dist(c.player,c.boss)>CombatRules.pistol.range){flash('Alcance máximo: 2 quadrados.');return false}const d20=roll(20),bonus=S.sector==='DOUTRINA'?1:0,result=CombatRules.hit(c,d20,bonus);notifyRoll('D20 '+d20+' + '+(bonus+result.protection)+' · '+(result.hit?'ACERTO':'ERRO'));if(result.hit){const actual=CombatRules.damage(c,damage);if(extraWeak)c.weak=1;audio('attack');record(c,name+': '+actual+' de dano.'+(result.protection?' Firmeza da sequência de falhas: +'+result.protection+' no teste.':''))}else{audio('bad');record(c,name+': o golpe falhou. A próxima tentativa recebe +'+Math.min(6,c.badRolls*2)+'.')}return result.hit}

function checkCombatEnd(){const c=S.combat;if(!c)return false;if(c.bossHp<=0){if(S.outcome!=='victory'){S.fame+=1;S.sanity=clamp(S.sanity-1,0,10)}S.outcome='victory';persist();Cinematics.transitionScene(()=>{S.stage='victory-eye';persist();render()});return true}if(c.hp<=0){S.outcome='defeat';S.stage='ending';persist();render();return true}return false}

function animateCardFlight(uid,kind){const card=[...document.querySelectorAll('.card-item')].find(el=>el.dataset.value===uid);if(!card||typeof card.animate!=='function')return;const from=card.getBoundingClientRect();const copy=card.cloneNode(true);copy.removeAttribute('data-action');copy.style.position='fixed';copy.style.left=`${from.left}px`;copy.style.top=`${from.top}px`;copy.style.width=`${from.width}px`;copy.style.height=`${from.height}px`;copy.style.margin='0';copy.style.transform='none';copy.style.zIndex='180';copy.style.pointerEvents='none';copy.classList.remove('is-dealt');document.body.append(copy);const tx=window.innerWidth/2-from.left-from.width/2,ty=kind==='burn'?170-from.top:window.innerHeight*.38-from.top;const anim=copy.animate([{transform:'translate(0,0) rotate(0deg) scale(1)',opacity:1},{offset:.76,transform:`translate(${tx*.8}px,${ty*.8}px) rotate(${kind==='burn'?'-15deg':'0deg'}) scale(.78)`,opacity:.85},{transform:`translate(${tx}px,${ty}px) rotate(${kind==='burn'?'-30deg':'0deg'}) scale(.2)`,opacity:0}],{duration:motionOK()?(kind==='burn'?900:1150):180,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});anim.finished.finally(()=>copy.remove());}
let resolvingAction=false;
function combatToken(side){return document.querySelector('.combat .unit.'+side)}
function beginResolution(){resolvingAction=true;document.body.classList.add('is-resolving')}
function endResolution(){resolvingAction=false;document.body.classList.remove('is-resolving')}
async function playCard(uid){const c=S.combat;if(!c||c.phase!=='player'||c.action<1||resolvingAction)return;const card=getCard(c,uid);if(!card)return;const d=CARD_LIBRARY[card.type];if(needsTarget(d)&&dist(c.player,c.boss)>2){flash('Aproxime-se: alcance máximo de 2 quadrados.');return}
 beginResolution();try{const hpBefore=c.hp,bossBefore=c.bossHp;let hit=true;selectedCardId=null;animateCardFlight(uid,'play');c.hand=c.hand.filter(x=>x.uid!==uid);c.discard.push(card);c.action--;
 const die=roll(6),ok=CombatRules.activate(c,d,die);notifyRoll('D6 '+die+' · '+(ok?'ATIVOU':'FALHOU')+' ['+d.dice.join(' / ')+']');
 if(!ok){audio('bad');record(c,d.name+': D6 '+die+' não ativou a carta.'+(c.badRolls>=2?' Ação devolvida e +2 escudo pela sequência de falhas.':''));await BattleFX.cast(()=>combatToken('player'),null,{kind:'fizzle'});return}
 audio('good');switch(d.effect){
 case'attack':hit=attackRoll(c,d.power,d.name);break;
 case'attackWeak':hit=attackRoll(c,d.power,d.name,true);break;
 case'shield':c.shield+=d.power;record(c,d.name+': +'+d.power+' escudo.');break;
 case'heal':{const actual=Math.min(d.power,c.maxHp-c.hp);c.hp+=actual;record(c,d.name+': +'+actual+' Vida.');break}
 case'move':c.move+=2;c.shield+=2;record(c,d.name+': +2 passos e +2 escudo.');break;
 case'signature':switch(S.sector){case'INCIDÊNCIA':c.shield+=7;record(c,'Incidência: +7 de escudo.');break;case'RELAÇÃO':c.shield+=3;drawCard(c,1);record(c,'Relação: +3 escudo e +1 carta.');break;case'SOCIALISTA':c.hp=Math.min(c.maxHp,c.hp+5);c.shield+=2;record(c,'Socialista: +5 Vida e +2 escudo.');break;case'JUSTIÇA':hit=attackRoll(c,6,'Sentença de Justiça');break;case'DOUTRINA':hit=attackRoll(c,7,'Execução de Doutrina');break}break;
 }
 persist();render();const offensive=needsTarget(d),kind=offensive?'attack':(d.effect==='heal'||d.effect==='signature'&&S.sector==='SOCIALISTA')?'heal':d.effect==='move'?'move':'shield';await BattleFX.cast(()=>combatToken('player'),()=>combatToken(offensive?'boss':'player'),{kind,hit,amount:offensive?bossBefore-c.bossHp:c.hp-hpBefore});checkCombatEnd();
 }finally{endResolution()}}
async function shoot(){const c=S.combat;if(!c||c.phase!=='player'||c.action<1||resolvingAction)return;if(dist(c.player,c.boss)>2){flash('A Pistola alcança somente 2 quadrados.');return}beginResolution();try{const before=c.bossHp;c.action--;const hit=attackRoll(c,CombatRules.pistol.damage,'Pistola de serviço');await BattleFX.cast(()=>combatToken('player'),()=>combatToken('boss'),{kind:'attack',hit,amount:before-c.bossHp});checkCombatEnd()}finally{endResolution()}}

function burn(uid){const c=S.combat;if(!c||c.phase!=='player'||c.usedBurn)return;let card=getCard(c,uid);if(!card)return;animateCardFlight(uid,'burn');selectedCardId=null;c.hand=c.hand.filter(x=>x.uid!==uid);c.banned.push(card);c.move+=2;c.usedBurn=true;record(c,`${CARD_LIBRARY[card.type].name} foi queimada. +2 passos extras.`)}
function paper(){const c=S.combat;if(!c||c.phase!=='player'||c.paperCd>0)return;if(c.hand.length>=7){flash('Sua mão está cheia. Use ou queime uma carta antes de comprar.');return}c.paperCd=2;drawCard(c,1);record(c,'Papel e Caneta: +1 carta de Ação. Aguarde 2 turnos próprios de recarga.');audio('click')}
function findPath(start,end,block){if(!inBounds(end.x,end.y))return null;const queue=[[start]],seen=new Set([start.x+','+start.y]);for(let i=0;i<queue.length;i++){const p=queue[i],q=p[p.length-1];if(q.x===end.x&&q.y===end.y)return p;for(const [dx,dy] of [[0,1],[0,-1],[1,0],[-1,0]]){const next={x:q.x+dx,y:q.y+dy},k=next.x+','+next.y;if(inBounds(next.x,next.y)&&!seen.has(k)&&!(block&&next.x===block.x&&next.y===block.y)){seen.add(k);queue.push([...p,next])}}}return null}
async function move(x,y){const c=S.combat;if(!c||c.phase!=='player'||Cinematics.busy)return;const route=findPath(c.player,{x,y},c.boss);if(!route||route.length<2||route.length-1>c.move)return;const unit=$('.unit.player'),board=$('.combat-floor'),base=board.getBoundingClientRect();const centers=route.map(p=>{const el=$('.tile[data-value="'+p.x+','+p.y+'"]');el.classList.add('path-preview');const r=el.getBoundingClientRect();return{x:r.left-base.left+r.width/2,y:r.top-base.top+r.height/2}});const traveler=unit.cloneNode(true);traveler.classList.add('walking-token');board.append(traveler);unit.style.visibility='hidden';await Cinematics.walkToTile(centers,{element:traveler,stepMs:500,onStep:i=>{c.player={...route[i]};c.move--;persist()}});traveler.remove();record(c,'Seu Searcher percorreu '+(route.length-1)+' quadrados.');}

async function enemyTurn(){if(S.stage!=='combat'||!S.combat||S.combat.phase!=='enemy')return;const c=S.combat;if(dist(c.player,c.boss)>1){const route=findPath(c.boss,c.player);if(route&&route.length>2){const board=$('.combat-floor'),unit=$('.unit.boss'),base=board.getBoundingClientRect(),points=route.slice(0,2).map(p=>{const r=$('.tile[data-value="'+p.x+','+p.y+'"]').getBoundingClientRect();return{x:r.left-base.left+r.width/2,y:r.top-base.top+r.height/2}}),traveler=unit.cloneNode(true);traveler.classList.add('walking-token');board.append(traveler);unit.style.visibility='hidden';await Cinematics.walkToTile(points,{element:traveler,stepMs:500});c.boss={...route[1]};traveler.remove()}}if(S.combat!==c||S.stage!=='combat')return;beginResolution();try{const before=c.hp,intent=c.intent.kind,hit=intent==='area'?c.intent.cells.some(p=>p.x===c.player.x&&p.y===c.player.y):intent==='strike'?dist(c.player,c.boss)<=2:true;c.last=CombatRules.resolve(c,S);c.log.push(c.last);persist();render();await BattleFX.cast(()=>combatToken('boss'),()=>combatToken(intent==='guard'?'boss':'player'),{kind:intent==='guard'?'shield':intent==='psych'?'psych':'attack',hit,amount:before-c.hp});if(checkCombatEnd())return;}finally{endResolution()}c.phase='player';c.round++;c.action=1;c.move=2;c.usedBurn=false;c.paperCd=Math.max(0,c.paperCd-1);c.intent=CombatRules.plan(c.round,c.player);drawCard(c,1);persist();render();}
function endTurn(){selectedCardId=null;const c=S.combat;if(!c||c.phase!=='player'||Cinematics.busy)return;c.phase='enemy';c.last='O Portão responde à sua ação…';persist();render();setTimeout(()=>{if(S.combat===c)enemyTurn()},850)}

function startBattle(){S.combat=initialCombat();patch({stage:'combat'});flash('MINI TUTORIAL: D6 sempre ativa. D20 acerta a partir de 2. Aproxime-se e experimente uma carta.')}
function determineSector(sin){const scores={...S.scores};const low=(sin||'').toLocaleLowerCase('pt-BR');const tags=[[/viol[eê]ncia|agress|for[cç]a|prote[gç]/,'INCIDÊNCIA'],[/mentir|negoci|manipul|trapace/,'RELAÇÃO'],[/ajuda|abandono|ego[ií]sm|trai[cç][aã]o coletiva/,'SOCIALISTA'],[/injust|culp|ju[ií]zo|omiss[aã]o/,'JUSTIÇA'],[/vingan[cç]|matar|assassin|ódio/,'DOUTRINA']];for(const [pattern,s] of tags)if(pattern.test(low)){scores[s]+=.25;break}return SECTORS.slice().sort((a,b)=>scores[b]-scores[a])[0]}
function restart(){if(!confirm('Apagar seu progresso salvo neste navegador e reiniciar o prólogo?'))return;S=defaultState();persist();render()}
function action(type,v){if(resolvingAction&&!['audio','settings','motion'].includes(type))return;if(Cinematics.busy&&!['audio','settings','motion'].includes(type))return;switch(type){
 case'open-eye':Cinematics.playEyeIntro(true);break;
 case'reveal-community':if(S.outcome==='victory'&&S.stage==='victory-eye'){audio('eye');Cinematics.transitionScene(()=>{S.flags.communitySeen=true;patch({stage:'community'})})}break;
 case'view-ending':if(S.outcome==='victory')patch({stage:'ending'});break;
 case'postgame-eye':if(S.outcome==='victory')Cinematics.transitionScene(()=>patch({stage:'victory-eye'}));break;
 case'settings':$('#volume').value=S.volume;$('#text-speed').value=S.textSpeed;$('#settings-dialog').showModal();break;
 case'create':patch({stage:'gender'});break;
 case'gender':patch({gender:v,stage:'name'});break;
 case'submit-name':{const name=$('#player-name')?.value.trim().replace(/\s+/g,' ');if(!name){flash('Informe um nome para seu Searcher.');return}patch({name:name.slice(0,24),stage:'quiz'});break}
 case'answer':{const i=Number(v),q=QUESTIONS[S.quizIndex];if(!q||!q.o[i])return;S.scores[q.o[i][1]]++;S.quizIndex++;S.stage=S.quizIndex>=QUESTIONS.length?'sin':'quiz';persist();render();break}
 case'submit-sin':{const sin=$('#sin-entry')?.value.slice(0,300)||'';patch({sin,sector:determineSector(sin),stage:'class'});break}
 case'begin-story':goNode('arrival');break;
 case'node':goNode(v);break;
 case'explore':patch({stage:'explore'});break;
 case'room':enterRoom(v);break;
 case'find':giveClue(v);break;
 case'store-evidence':{const id=S.evidenceId,clue=CLUES[id];if(clue&&!S.clues.includes(id)){S.clues.push(id);S.moral=clamp(S.moral+clue.moral,0,10);S.flags.lastEvidence=id;for(const flag of clue.flags||[])S.flags[flag]=true;audio('good')}S.stage='explore';persist();render();flash('DOCUMENTO ARQUIVADO · releia no dossiê.');if(id==='child'&&!S.flags.childProtected){S.flags.childProtected=true;goNode('childProtect')}break}
 case'reread':S.evidenceId=v;patch({stage:'evidence'});break;
 case'keep-reading':flash('Leia os detalhes do documento antes de arquivá-lo.');break;
 case'talk':goNode('greeting');break;
 case'confront':goNode('confrontation');break;
 case'journal':openJournal();break;
 case'stance':chooseStance(v);break;
 case'decision':makeDecision(v);break;
 case'force-door':if(S.moral<1){flash('Você precisa de 1 Moral para forçar a porta.');break}S.moral--;S.flags.forcedDoor=true;goNode('lockedRoom');break;
 case'collect':collect();break;
 case'wake-hell':goNode('hell1');break;
 case'battle':startBattle();break;
 case'select-card':if(S.combat?.phase!=='player')return;selectedCardId=selectedCardId===v?null:v;render();audio('click');break;
 case'play-card':playCard(v);break;
 case'burn':burn(v);break;
 case'shoot':shoot();break;
 case'paper':paper();break;
 case'move':{const [x,y]=v.split(',').map(Number);move(x,y);break}
 case'end-turn':endTurn();break;
 case'retry-boss':startBattle();break;
 case'motion':S.motionFull=!S.motionFull;document.documentElement.dataset.motion=S.motionFull?'full':'auto';persist();refreshNav();break;
 case'audio':S.audio=!S.audio;persist();refreshNav();if(S.audio)audio('good');break;
 case'restart':restart();break;
 }}
document.addEventListener('click',e=>{if(e.target.closest('.typewritten')){advanceDialogue();return}const b=e.target.closest('[data-action]');if(!b||b.disabled||b.closest('[inert]'))return;const a=b.dataset.action,v=b.dataset.value||'';if(a!=='audio'&&a!=='open-eye')audio('click');action(a,v)});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(S.stage==='vn'&&(e.key===' '||e.key==='Enter')&&!['BUTTON','INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();advanceDialogue();return}if(e.key==='Enter'&&S.stage==='name'){e.preventDefault();action('submit-name','')}if(S.stage==='vn'&&/^[1-9]$/.test(e.key)){const box=$('.dialogue-choices');if(box&&!box.inert)box.children[Number(e.key)-1]?.click()}});
function refreshNav(){const current=$('.nav');if(current)current.outerHTML=nav()}
document.addEventListener('pointermove',e=>{const x=(e.clientX/window.innerWidth-.5)*9,y=(e.clientY/window.innerHeight-.5)*8;document.documentElement.style.setProperty('--eye-x',`${x}px`);document.documentElement.style.setProperty('--eye-y',`${y}px`)});
if(PREVIEW_SCENE==='combat')S.combat=initialCombat();
render();
if(S.stage==='combat'&&S.combat?.bossHp<=0)checkCombatEnd();
else if(S.stage==='combat'&&S.combat?.phase==='enemy')setTimeout(enemyTurn,850);
